package main

import (
	"go/format"
	"os"
	"regexp"
	"strings"
	"testing"
)

func read(t *testing.T, name string) []byte {
	t.Helper()
	b, err := os.ReadFile("testdata/" + name)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func TestGenerate(t *testing.T) {
	out, err := generate(read(t, "themes.ts"), read(t, "theme.css"), "test source")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := format.Source(out); err != nil {
		t.Fatalf("output is not valid Go: %v\n%s", err, out)
	}
	s := string(out)
	for _, want := range []string{
		"// Code generated by internal/cmd/shadcngen; DO NOT EDIT.",
		"test source",
		`"oklch(1 0 0 / 10%)"`,
		`"sidebar-primary": "oklch(0.488 0.243 264.376)"`,
		`shadcnBaseNames = []string{"neutral"}`,
		`shadcnColorNames = []string{"amber"}`,
	} {
		if !strings.Contains(s, want) {
			t.Errorf("output lacks %s", want)
		}
	}
	if !regexp.MustCompile(`"mauve":\s+\{"oklch\(98\.5% 0 none\)"`).MatchString(s) {
		t.Error("output lacks the mauve scale")
	}
	if strings.Contains(s, "0.625rem") {
		t.Error("radius must not be in the table")
	}
	if strings.Contains(s, `"red"`) {
		t.Error("only gray families belong in tailwindV4Scales")
	}
}

func TestGenerateMissingStep(t *testing.T) {
	css := strings.Replace(string(read(t, "theme.css")), "--color-neutral-950", "--color-neutral-x", 1)
	if _, err := generate(read(t, "themes.ts"), []byte(css), "x"); err == nil {
		t.Fatal("expected an error for a missing neutral-950")
	}
}
